int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<pair<int, int>> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i].first >> a[i].second;
    // 先按 second 升序，相同按 first 升序
    sort(a.begin(), a.end(), [](const auto &x, const auto &y) {
        if (x.second != y.second) return x.second < y.second;
        return x.first < y.first;
    });
    for (int i = 0; i < n; ++i)
        cout << a[i].first << ' ' << a[i].second << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<int> a(n * m);
    for (int i = 0; i < n * m; ++i) cin >> a[i];
    int up = 0, down = n - 1, left = 0, right = m - 1;
    bool first = true;
    auto out = [&](int v) {
        if (!first) cout << ' ';
        first = false;
        cout << v;
    };
    while (up <= down && left <= right) {
        for (int c = left; c <= right; ++c) out(a[up * m + c]);
        ++up;
        for (int r = up; r <= down; ++r) out(a[r * m + right]);
        --right;
        if (up <= down) {
            for (int c = right; c >= left; --c) out(a[down * m + c]);
            --down;
        }
        if (left <= right) {
            for (int r = down; r >= up; --r) out(a[r * m + left]);
            ++left;
        }
    }
    cout << '\n';
    return 0;
}

