def solve():
    import sys
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1 + n]
    lt, i, gt = 0, 0, n - 1
    while i <= gt:
        if a[i] == 0:
            a[lt], a[i] = a[i], a[lt]
            lt += 1
            i += 1
        elif a[i] == 2:
            a[gt], a[i] = a[i], a[gt]
            gt -= 1  # i 不动：换来的元素还没检查
        else:
            i += 1
    sys.stdout.write(" ".join(map(str, a)))


if __name__ == "__main__":
    solve()

