def solve():
    import sys
    data = list(map(int, sys.stdin.read().split()))
    if len(data) < 2:
        return
    n = data[0]
    a = data[1:1 + n]
    target = data[1 + n]
    lo, hi = 0, n - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            ans = mid
            break
        if a[mid] <= a[hi]:
            if a[mid] < target <= a[hi]:  # 右半有序
                lo = mid + 1
            else:
                hi = mid - 1
        else:
            if a[lo] <= target < a[mid]:  # 左半有序
                hi = mid - 1
            else:
                lo = mid + 1
    print(ans)


if __name__ == "__main__":
    solve()

